scripts.张宪对话.txt:
//和张宪的对话

	If ($Event == 440) @Event440;	
	If ($Event == 450) @Event450;
	
@Event440:
	Say("张宪：岳元帅正在主营帐里等着二位呢。", 0);
	Return;	
	
	
@Event450:
	Say("张宪：出了营门口，有一条小路通往金兵的后营。两位多保重！", 0);
	Return;

